-- Study Abroad country content, BATCH 27: Benin, Burkina Faso, Cote d'Ivoire, Mali, Niger, Togo, Guinea, Madagascar, Gabon.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('benin', 'burkina-faso', 'cote-divoire', 'mali', 'niger', 'togo', 'guinea', 'madagascar', 'gabon'));
UPDATE countries SET why_title = 'Why study in Benin?', why_body = '<p>Benin offers low-cost French-taught degrees at the University of Abomey-Calavi and the University of Parakou in a stable West African country.<ul><li>Low tuition</li><li>French-medium teaching</li><li>University of Abomey-Calavi</li><li>Strengths in agriculture, health and law</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>A <strong>student visa</strong> is needed, normally obtained from a Beninese embassy or consulate after admission. No official Beninese visa details were found.</p><ul><li>Admission letter and proof of enrolment</li><li>Proof of financial support and health insurance</li><li>Academic calendar runs October to July</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Beninese embassy and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>UAC uses a selective, entrance-exam-based admission policy; the faculty of sciences opened 2026 registration for graduates trained abroad.</p><ul><li>Academic transcripts and certificates, legalised</li><li>French language proof</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Aggregators conflict; no official international fees were found.</p><ul><li>uniRank: about US$1,000-$2,499 a year for UAC</li><li>Public universities: free to about US$300 a year (one guide); private: US$1,000-$4,000</li><li>Living costs: about US$250-$450 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (baccalauréat or equivalent)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree (licence)</li><li><strong>Language:</strong> French proof for French-taught programmes</li></ul>' WHERE slug = 'benin';
UPDATE countries SET why_title = 'Why study in Burkina Faso?', why_body = '<p>Burkina Faso has Université Joseph Ki-Zerbo and the 2iE engineering institute, with French-taught degrees at moderate fees; check current conditions.<ul><li>French-medium teaching</li><li>Joseph Ki-Zerbo University (Ouaga 1)</li><li>2iE engineering and water institute</li><li>WASCAL research programmes</li></ul></p><p>Check your government''s travel advice before planning.</p>', visa_title = 'Student visa and residence permit', visa_body = '<p>The only lead found is the official eVisa portal (Ministry of Security); actual student visa conditions were not found.</p><ul><li>Admission letter from a Burkinabe institution</li><li>Check the eVisa portal and the embassy</li><li>WASCAL programmes require citizenship of a WASCAL member country</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Burkina Faso eVisa portal and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>UJKZ master''s notices use a file fee (for example 15,500 FCFA for a 2026-27 microbiology master''s, files accepted 17 July to 14 August 2026).</p><ul><li>Academic transcripts and certificates, legalised</li><li>French language proof</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Fees vary by programme and by origin.</p><ul><li>UJKZ 2026-27 master''s notice: 1,500,000 FCFA a year for students outside the UEMOA zone</li><li>Another notice appears to set about 251,500 FCFA but is garbled; unverified</li><li>2iE fees: not found</li><li>Living costs: about US$250-$450 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (baccalauréat or equivalent)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree (licence)</li><li><strong>Language:</strong> French proof for French-taught programmes</li></ul>' WHERE slug = 'burkina-faso';
UPDATE countries SET why_title = 'Why study in Côte d''Ivoire?', why_body = '<p>Côte d''Ivoire is a French-speaking West African hub with Université Félix Houphouët-Boigny and the INP-HB engineering school.<ul><li>French-medium teaching</li><li>Université Félix Houphouët-Boigny in Abidjan</li><li>INP-HB in Yamoussoukro</li><li>Large regional economy</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Apply for a student visa at the nearest embassy or consulate after admission (secondary guides); no official 2026 checklist was found.</p><ul><li>Admission letter from an Ivorian institution</li><li>Proof of funds and health insurance</li><li>Campus France Côte d''Ivoire handles French-programme guidance</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Ivorian embassy and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university; INP-HB lists its applicant pages online.</p><ul><li>Academic transcripts and certificates, legalised</li><li>French language proof</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No official international fee schedule was found.</p><ul><li>A January 2026 report says UFHB registration fees were unchanged (unclear for foreign students)</li><li>Living costs: about US$300-$600 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (baccalauréat or equivalent)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree (licence)</li><li><strong>Language:</strong> French proof for French-taught programmes</li></ul>' WHERE slug = 'cote-divoire';
UPDATE countries SET why_title = 'Why study in Mali?', why_body = '<p>Mali has French-taught public universities in Bamako at very low fees, but conditions require careful checking.<ul><li>French-medium teaching</li><li>Public universities in Bamako</li><li>Very low tuition</li><li>Check current conditions</li></ul></p><p>Check your government''s travel advice before planning.</p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Apply for a student visa at the nearest embassy or consulate after admission (secondary guides); no official 2026 checklist was found.</p><ul><li>Admission letter from a Malian university</li><li>Visa for nationals of India, Pakistan, US and UK reported to be needed to enter Mali</li><li>Use the Malian diplomatic-missions visa portal and the Campus Mali admission portal</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Malian embassy and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply through the national Campus Mali portal or directly to universities.</p><ul><li>Academic transcripts and certificates, legalised</li><li>French language proof</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Sources disagree.</p><ul><li>Public universities: about US$40-$250 a year (guide)</li><li>Another guide found no published fees for foreign students</li><li>No government scholarship scheme for international students was found</li><li>Living costs: about US$200-$400 a month (guide)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (baccalauréat or equivalent)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree (licence)</li><li><strong>Language:</strong> Good French is required</li></ul>' WHERE slug = 'mali';
UPDATE countries SET why_title = 'Why study in Niger?', why_body = '<p>Niger has French-taught public universities, mainly Abdou Moumouni University in Niamey, at very low fees; check current conditions.<ul><li>French-medium teaching</li><li>Abdou Moumouni University</li><li>Very low tuition</li><li>Check current conditions</li></ul></p><p>Check your government''s travel advice before planning.</p>', visa_title = 'Student visa and residence permit', visa_body = '<p>International students admitted to Abdou Moumouni University need a <strong>student visa</strong> from a Nigerien embassy after receiving an admission letter; one guide cites about one to three weeks.</p><ul><li>Admission letter from the university</li><li>Eligible: students at AMU, accredited private institutes and holders of government or international scholarships</li><li>Confirm with the Nigerien embassy</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Nigerien embassy and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university.</p><ul><li>Academic transcripts and certificates, legalised</li><li>French language proof</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Sources conflict.</p><ul><li>uni2study: licence 10,000 FCFA a year and master''s/doctoral 50,000 FCFA (Niger and UEMOA nationals)</li><li>university.im: XOF 25,000-100,000 a year; another guide: US$800-$1,500 for international students</li><li>Living costs: about US$200-$400 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (baccalauréat or equivalent)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree (licence)</li><li><strong>Language:</strong> French proof for French-taught programmes</li></ul>' WHERE slug = 'niger';
UPDATE countries SET why_title = 'Why study in Togo?', why_body = '<p>Togo offers French-taught degrees at the University of Lomé and the University of Kara at moderate fees.<ul><li>French-medium teaching</li><li>University of Lomé</li><li>University of Kara</li><li>Peaceful coastal country</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>One guide says non-ECOWAS students apply online for an immigration visa for study (65,000 F CFA, checked October 2026) and then for a residence card; the e-visa is up to 90 days. ECOWAS nationals have a separate arrangement.</p><ul><li>Admission letter from the university</li><li>Immigration visa for study and then a residence card in Togo</li><li>Foreign diploma holders go through the Certification Division of the Directorate of Academic Affairs for first registration</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Togo e-visa portal and the University of Lomé site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>The University of Lomé has foreign-student and registration pages in French.</p><ul><li>Academic transcripts and certificates, legalised</li><li>French language proof</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Estimates vary.</p><ul><li>UL fee for foreigners about US$1,000 a year (guide); others US$1,000-$2,500; uniRank 0-999</li><li>No Togolese government scholarship for foreign students found; UL mobility programmes may offer some</li><li>Living costs: about US$250-$450 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (baccalauréat or equivalent)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree (licence)</li><li><strong>Language:</strong> French proof for French-taught programmes</li></ul>' WHERE slug = 'togo';
UPDATE countries SET why_title = 'Why study in Guinea?', why_body = '<p>Guinea has French-taught public universities and a few private institutions in Conakry and Kankan.<ul><li>French-medium teaching</li><li>Gamal Abdel Nasser University of Conakry</li><li>Kofi Annan University of Guinea (private)</li><li>Mining and agriculture strengths</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>No authoritative visa requirements were found; an April 2026 blog identifies a long-stay student visa category only.</p><ul><li>Admission letter from a Guinean institution</li><li>Check the Guinean embassy and the ministry of higher education</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Guinean embassy and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Ask each university in writing for admission requirements.</p><ul><li>Academic transcripts and certificates, legalised</li><li>French language proof</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No published schedule for foreign students.</p><ul><li>Study Abroad Courses estimate: US$1,200-$2,500 a year (uncited)</li><li>Kofi Annan University of Guinea (private): US$2,500 a year minimum for foreigners</li><li>Public universities usually have no dormitories</li><li>Living costs: about US$250-$450 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (baccalauréat or equivalent)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree (licence)</li><li><strong>Language:</strong> French proof for French-taught programmes</li></ul>' WHERE slug = 'guinea';
UPDATE countries SET why_title = 'Why study in Madagascar?', why_body = '<p>Madagascar offers low-cost French- and Malagasy-taught degrees at the University of Antananarivo and regional universities, with unique biodiversity.<ul><li>Very low public tuition</li><li>French and Malagasy instruction</li><li>University of Antananarivo</li><li>Biodiversity and environment studies</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>A <strong>student visa</strong> is needed; apply at a Malagasy embassy or consulate after acceptance. Campus France Madagascar references a long-stay study visa process.</p><ul><li>Admission letter from the university</li><li>Proof of funds and health insurance</li><li>No official requirements were found</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Malagasy embassy and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>The University of Antananarivo is selective with entrance examinations (uniRank); confirm if this applies to international applicants.</p><ul><li>Academic transcripts and certificates, legalised</li><li>French language proof</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Third-party figures only.</p><ul><li>Public universities: about MGA 50,000-300,000 a year (guide)</li><li>Private: MGA 1,000,000-5,000,000</li><li>Living costs: about US$250-$450 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (baccalauréat or equivalent)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree (licence)</li><li><strong>Language:</strong> French proof for French-taught programmes</li></ul>' WHERE slug = 'madagascar';
UPDATE countries SET why_title = 'Why study in Gabon?', why_body = '<p>Gabon offers French-taught degrees at Université Omar Bongo and USTM in a country with oil, forestry and biodiversity sectors.<ul><li>French-medium teaching</li><li>Université Omar Bongo, USTM</li><li>Low public tuition</li><li>Rainforest biodiversity</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>A <strong>student visa</strong> is needed from a Gabonese embassy or consulate; one guide says it is valid only for arrival by air at Libreville and takes 72 hours. Longer stays need a residence card (carte de séjour) from the DGDI.</p><ul><li>Admission letter from the university</li><li>Residence card for longer stays</li><li>Official pages describe no student work rights or post-study work route</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Gabonese embassy, DGDI and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Contact the university registrar (scolarité); no English-taught degrees were found at UOB or USTM.</p><ul><li>Academic transcripts and certificates, legalised</li><li>French language proof</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No official schedule found.</p><ul><li>Public universities: about XAF 50,000-200,000 a year (aggregator; applicability to foreigners unclear)</li><li>Living costs: about US$500-$900 a month (one source)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (baccalauréat or equivalent)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree (licence)</li><li><strong>Language:</strong> French proof for French-taught programmes</li></ul>' WHERE slug = 'gabon';
COMMIT;
